(function () {
    // ---- Turbo promotion tooltip: Live Preview + Upgrade override --------------
    // Elementor (with Pro active) renders the widget promotion as a MUI tooltip whose
    // "Upgrade" CTA is a plain anchor:
    //   <a href="https://go.elementor.com/go-pro-<widget-name>" target="_blank">
    // The widget name is embedded in that href, so we detect OUR widgets by matching
    // that name against the list passed from PHP (wp_localize_script). For OUR widgets
    // we (a) inject a "Live Preview" button and (b) point "Upgrade" to our pricing
    // page. Any other addon's / Elementor's own promotion links stay untouched.
    const TURBO_DATA = (typeof TurboPromoData !== 'undefined') ? TurboPromoData : {};
    const TURBO_PRICING_URL = TURBO_DATA.pricingUrl || 'https://turbo-addons.com/pricing/';
    const TURBO_NAMES = TURBO_DATA.widgetNames || [];

    // Live Preview links, keyed by widget name (the name embedded in the go-pro href).
    // Edit any URL below if a preview page differs on turbo-addons.com.
    const TURBO_PREVIEW_URLS = {
        'trad-timeline-story'            : 'https://turbo-addons.com/time-line/',
        'trad-progress-milestone'        : 'https://turbo-addons.com/progress-bar/',
        'trad-review-archive'            : 'https://turbo-addons.com/review-archive/',
        'visitor-count'                  : 'https://turbo-addons.com/active-visitor-viewer/',
        'trad_3d_carousel'               : 'https://turbo-addons.com/3d-carousel/',
        'trad_testimonial_slider'        : 'https://turbo-addons.com/testimonial-slider/',
        'trad-flip-box'                  : 'https://turbo-addons.com/3d-flip-box/',
        'turbo-date-time'                : 'https://turbo-addons.com/local-date/',
        'turbo-post-date'                : 'https://turbo-addons.com/post-date/',
        'category-post-count'            : 'https://turbo-addons.com/elementor-post-category/',
        'list-icon'                      : 'https://turbo-addons.com/icon-list/',
        'advance-featured-card'          : 'https://turbo-addons.com/advance-featured-card/',
        'post-list'                      : 'https://turbo-addons.com/post-category-list/',
        'category-filter-tab'            : 'https://turbo-addons.com/post-filter-tab/',
        'image-auto-scrolling'           : 'https://turbo-addons.com/image-vertical-scrolling/',
        'hero-slider'                    : 'https://turbo-addons.com/hero-slider/',
        'tour-guide'                     : 'https://turbo-addons.com/user-walkthrough/',
        'text-gradient'                  : 'https://turbo-addons.com/text-gradient/',
        'woo-product-card'               : 'https://turbo-addons.com/woo-products-card/',
        'woo-product-pagination'         : 'https://turbo-addons.com/woo-pagination-elementor-widget/',
        'woo-category'                   : 'https://turbo-addons.com/woo-category-card/',
        'woo-mini-cart'                  : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-breadcrumb'         : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-button'             : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-cart'               : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-description'        : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-image'              : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-meta'               : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-navigation'         : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-price'              : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-rating'             : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-related'            : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-short-description'  : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-stock'              : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-tab'                : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'woo-product-title'              : 'https://turbo-addons.com/product/apple-reveals-apple-watch-series-7-featuring-a-larger-more/',
        'trad-flip-book'                 : 'https://turbo-addons.com/pdf-flip-book/',
        'csv-data-table'                 : 'https://turbo-addons.com/advanced-table/',
        'trad-advanced-search'           : 'https://turbo-addons.com/advance-search/',
        'trad-off-canvas'                : 'https://turbo-addons.com/off-canvas/',
        'trad-whatsapp'                  : 'https://turbo-addons.com/whatsapp/',
        'trad-hotspot'                   : 'https://turbo-addons.com/image-hotspot/'
    };

    // Return the OUR widget name embedded in a go-pro href, or null.
    function turboMatchName(href) {
        if (!href || href.indexOf('go-pro-') === -1) return null;
        for (var i = 0; i < TURBO_NAMES.length; i++) {
            var n = TURBO_NAMES[i];
            if (!n) continue;
            var dash  = n.replace(/_/g, '-');
            var under = n.replace(/-/g, '_');
            if (href.indexOf('go-pro-' + n) !== -1 ||
                href.indexOf('go-pro-' + dash) !== -1 ||
                href.indexOf('go-pro-' + under) !== -1) {
                return n;
            }
        }
        return null;
    }

    function turboPreviewUrlFor(name) {
        if (!name) return null;
        return TURBO_PREVIEW_URLS[name] ||
               TURBO_PREVIEW_URLS[name.replace(/_/g, '-')] ||
               TURBO_PREVIEW_URLS[name.replace(/-/g, '_')] || null;
    }

    // Runs whenever the tooltip is inserted/updated: inject Live Preview + retarget Upgrade.
    const turboEnhance = function () {
        parent.document.querySelectorAll('a[href*="go-pro-"]').forEach(function (upgradeLink) {
            if (upgradeLink.dataset.turboProcessed === '1') return;

            var name = turboMatchName(upgradeLink.getAttribute('href'));
            if (!name) return; // not one of ours — leave it alone

            // (a) Inject a "Live Preview" button and place both CTAs side by side.
            var previewUrl = turboPreviewUrlFor(name);
            if (previewUrl && !(upgradeLink.parentNode &&
                    upgradeLink.parentNode.classList.contains('turbo-cta-row'))) {
                var preview = document.createElement('a');
                preview.className = upgradeLink.className + ' turbo-live-preview-btn';
                preview.textContent = 'Live Preview';
                preview.href = previewUrl;
                preview.target = '_blank';
                preview.rel = 'noopener';
                // Outlined look so it reads as secondary next to the filled Upgrade button.
                preview.style.background = '#ffffff';
                preview.style.color = '#93003c';
                preview.style.boxShadow = 'inset 0 0 0 1px #93003c';
                preview.style.margin = '0';

                // Wrap both buttons in a flex row so they sit side by side.
                var row = document.createElement('div');
                row.className = 'turbo-cta-row';
                row.style.display = 'flex';
                row.style.flexDirection = 'row';
                row.style.flexWrap = 'wrap';
                row.style.alignItems = 'center';
                row.style.justifyContent = 'flex-end';
                row.style.gap = '8px';

                upgradeLink.parentNode.insertBefore(row, upgradeLink);
                row.appendChild(preview);
                row.appendChild(upgradeLink);
                upgradeLink.style.margin = '0';
            }

            // (b) Point the Upgrade button to our pricing page.
            upgradeLink.setAttribute('href', TURBO_PRICING_URL);
            upgradeLink.setAttribute('target', '_blank');
            upgradeLink.setAttribute('rel', 'noopener');
            upgradeLink.dataset.turboProcessed = '1';
        });
    };
    new MutationObserver(turboEnhance).observe(parent.document.body, { childList: true, subtree: true });

    // Capture-phase click fallback, in case a click on the Upgrade CTA beats the
    // rewrite above (only fires for OUR go-pro links; preview links are left alone).
    parent.document.addEventListener('click', function (e) {
        var a = e.target.closest && e.target.closest('a');
        if (!a) return;
        if (a.classList.contains('turbo-live-preview-btn')) return; // let preview open normally
        if (!turboMatchName(a.getAttribute('href'))) return;
        e.preventDefault();
        e.stopImmediatePropagation();
        window.open(TURBO_PRICING_URL, '_blank', 'noopener');
    }, true);
    // ----------------------------------------------------------------------------
})();
